353	func (req IssueRequest) validatePresent() error {
354		missing := []string{}
355		if strings.TrimSpace(req.Operator) == "" {
356			missing = append(missing, "operator")
357		}
358		if strings.TrimSpace(req.Reason) == "" {
359			missing = append(missing, "reason")
360		}
361		if strings.TrimSpace(req.RequestID) == "" {
362			missing = append(missing, "request_id")
363		}
364		if strings.TrimSpace(req.ItemID) == "" {
365			missing = append(missing, "item_id")
366		}
367		if strings.TrimSpace(req.SeriesID) == "" {
368			missing = append(missing, "series_id")
369		}
370		if strings.TrimSpace(req.BatchNo) == "" {
371			missing = append(missing, "batch_no")
372		}
373		if strings.TrimSpace(req.HolderID) == "" {
374			missing = append(missing, "holder_id")
375		}
376		if len(missing) > 0 {
377			return fmt.Errorf("%w: 发行请求缺少必填字段 %s", ErrInvalidArgument, strings.Join(missing, ", "))
378		}
379		return nil
380	}
381	
382	func issueParamsSig(req IssueRequest) string {
383		b, _ := json.Marshal(struct {
384			Kind     string `json:"kind"`
385			ItemID   string `json:"item_id"`
386			SeriesID string `json:"series_id"`
387			BatchNo  string `json:"batch_no"`
388			Metadata string `json:"metadata"`
389			HolderID string `json:"holder_id"`
390			Reason   string `json:"reason"`
391		}{"issue", req.ItemID, req.SeriesID, req.BatchNo, req.Metadata, req.HolderID, req.Reason})
392		return string(b)
393	}
394	
395	// Issue 发行一件藏品。成功后持有版本为 1，初始持有人为 req.HolderID。
396	// 操作者必须是系列创建账户且可用，初始持有人必须已登记且可用，系列未
397	// 封存，藏品编号从未使用过。同一 (操作者, 请求号) 且业务参数相同的
398	// 重复提交返回首次结果；参数不同返回 ErrRequestConflict。
399	//
400	// 状态类拒绝的落盘失败时，与整批发行一致：返回保存错误（保留实际写入
401	// 错误）而非该业务错误，结果为空（无藏品编号、无持有人、无版本、无历史
402	// 序号、业务错误为空、不标回放），请求号不被这次未保存的拒绝占用；保存
403	// 条件恢复后用完全相同的请求重提，按当时的业务状态重新判断：拒绝条件仍
404	// 在则重新保存此次拒绝并返回对应业务错误，状态已变为满足请求则正常发行。
405	func (r *Registry) Issue(req IssueRequest) (IssueResult, error) {
406		if err := req.validatePresent(); err != nil {
407			return IssueResult{}, err
408		}
409		r.mu.Lock()
410		defer r.mu.Unlock()
411		if err := r.checkOpen(); err != nil {
412			return IssueResult{}, err
413		}
414	
415		key := requestKey(req.Operator, req.RequestID)
416		sig := issueParamsSig(req)
417		if prev, ok := r.state.Requests[key]; ok {
418			return r.replayIssue(prev, sig)
419		}
420	
421		bizErr := r.checkIssue(req)
422		if bizErr != nil {
423			if !isValidationErr(bizErr) {
424				// 状态类业务拒绝（封存、停用、无权、编号已用等）占用请求号并
425				// 落盘：相同参数重提永远返回这一次拒绝，即使状态后来变化。
426				r.state.Requests[key] = request{
427					Operator: req.Operator, RequestID: req.RequestID, Kind: "issue",
428					Params: sig, Rejected: true, Reason: errCode(bizErr),
429					ItemID: req.ItemID,
430				}
431				if err := r.commit(); err != nil {
432					// 拒绝结果落盘失败：这次拒绝没有被记住，与整批发行一致——
433					// 不能只用业务错误掩盖保存错误，调用者稍后用原请求重提时
434					// 必须按当时状态重新判断，而不是回放一个实际没有保存的
435					// 拒绝。commit 失败时已按磁盘内容重建状态，请求记录随之
436					// 撤销；此处再删一次以覆盖磁盘暂时不可读、状态未能重建
437					// 的情形。整体返回空结果：无藏品编号、无持有人、无版本、
438					// 无历史序号、不标回放、结果中业务错误为空，error 保留
439					// 实际写入错误。
440					delete(r.state.Requests, key)
441					return IssueResult{}, err
442				}
443			}
444			// 校验类错误（引用不存在等）不占用请求号，也不改变任何状态。
445			return IssueResult{ItemID: req.ItemID, Err: bizErr}, bizErr
446		}
447	
448		seq := r.state.NextSeq + 1
449		r.state.NextSeq = seq
450		r.state.Items[req.ItemID] = item{
451			ID: req.ItemID, SeriesID: req.SeriesID, BatchNo: req.BatchNo,
452			Metadata: req.Metadata, IssuedTxID: seq,
453		}
454		r.state.Holdings[req.ItemID] = holding{ItemID: req.ItemID, OwnerID: req.HolderID, Version: 1}
455		r.state.History = append(r.state.History, historyEntry{
456			Seq: seq, Kind: "issue", ItemID: req.ItemID, Operator: req.Operator,
457			Reason: req.Reason, RequestID: req.RequestID,
458			FromID: "", ToID: req.HolderID, FromVersion: 0, ToVersion: 1,
459		})
460		r.state.Requests[key] = request{
461			Operator: req.Operator, RequestID: req.RequestID, Kind: "issue",
462			Params: sig, ItemID: req.ItemID, ToID: req.HolderID, Version: 1, TxSeq: seq,
463		}
464		if err := r.commit(); err != nil {
465			return IssueResult{}, err
466		}
467		return IssueResult{ItemID: req.ItemID, OwnerID: req.HolderID, Version: 1, TxSeq: seq}, nil
468	}
469	
470	// checkIssue 按单件发行的优先级执行与整批共用的发行资格规则：参数合法
471	// 后，操作者的登记/停用问题优先于系列问题，系列问题内部依次为不存在、
472	// 已封存、操作者不是创建账户，藏品编号已占用又优先于初始持有人问题。
473	func (r *Registry) checkIssue(req IssueRequest) error {
474		return r.checkSingleIssueEligibility(req.Operator, req.SeriesID, req.ItemID, req.HolderID)
475	}
476	
477	func (r *Registry) replayIssue(prev request, sig string) (IssueResult, error) {
478		if prev.Kind != "issue" || prev.Params != sig {
479			return IssueResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
480				ErrRequestConflict, prev.Operator, prev.RequestID)
481		}
482		res := IssueResult{ItemID: prev.ItemID, OwnerID: prev.ToID, Version: prev.Version,
483			TxSeq: prev.TxSeq, Replayed: true}
484		if prev.Rejected {
485			res.Err = codeErr(prev.Reason)
486			return res, res.Err
487		}
488		return res, nil
489	}
