493	func (req TransferRequest) validatePresent() error {
494		missing := []string{}
495		if strings.TrimSpace(req.Operator) == "" {
496			missing = append(missing, "operator")
497		}
498		if strings.TrimSpace(req.Reason) == "" {
499			missing = append(missing, "reason")
500		}
501		if strings.TrimSpace(req.RequestID) == "" {
502			missing = append(missing, "request_id")
503		}
504		if strings.TrimSpace(req.ItemID) == "" {
505			missing = append(missing, "item_id")
506		}
507		if strings.TrimSpace(req.ExpectedOwner) == "" {
508			missing = append(missing, "expected_owner")
509		}
510		if strings.TrimSpace(req.ToID) == "" {
511			missing = append(missing, "to_id")
512		}
513		if req.ExpectedVer <= 0 {
514			missing = append(missing, "expected_version")
515		}
516		if len(missing) > 0 {
517			return fmt.Errorf("%w: 转让请求缺少必填字段 %s", ErrInvalidArgument, strings.Join(missing, ", "))
518		}
519		if req.Price < 0 {
520			return fmt.Errorf("%w: 成交价款 %d 不能为负", ErrInvalidArgument, req.Price)
521		}
522		return nil
523	}
524	
525	func transferParamsSig(req TransferRequest) string {
526		// Price 用 omitempty：价款为 0 时签名与引入价款前的旧格式一致，
527		// 旧登记册中落盘的请求仍可按原参数回放；改价则签名不同、按请求号
528		// 冲突拒绝。
529		b, _ := json.Marshal(struct {
530			Kind          string `json:"kind"`
531			ItemID        string `json:"item_id"`
532			ExpectedOwner string `json:"expected_owner"`
533			ExpectedVer   int64  `json:"expected_version"`
534			ToID          string `json:"to_id"`
535			Price         int64  `json:"price,omitempty"`
536			Reason        string `json:"reason"`
537		}{"transfer", req.ItemID, req.ExpectedOwner, req.ExpectedVer, req.ToID, req.Price, req.Reason})
538		return string(b)
539	}
