581	// Transfer 由当前持有人发起转让。接收人必须已登记、可用且不同于当前
582	// 持有人；请求必须给出期望持有人与期望版本，藏品不存在或持有人/版本
583	// 不符时返回业务拒绝且不改变任何状态。成交价款（分）由持有人填写，
584	// 非负、未填按 0；成功时按所属系列的版税规则一次落盘各收款账户的
585	// 应付明细与归转让前持有人的余款。同一 (操作者, 请求号) 的相同
586	// 请求重复提交（即使藏品后来已易手）返回首次结果。
587	//
588	// 状态类拒绝的落盘失败时，与整批转让一致：返回保存错误（保留实际写入
589	// 错误）而非该业务错误，结果为空（无藏品编号、无持有变化、无历史序号、
590	// 无金额、业务错误为空、不标回放），请求号不被这次未保存的拒绝占用；
591	// 保存条件恢复后用完全相同的请求重提，按当时的业务状态重新判断：拒绝
592	// 条件仍在则重新保存此次拒绝并返回对应业务错误，状态已变为满足请求则
593	// 正常转出。
594	//
595	// 成功转让同样以保存完成为准：持有换人、版本加一、转让历史、版税应付、
596	// 历史序号与请求结果都尚未写入原登记册而保存失败（如数据位置暂时无法
597	// 写入）时，返回实际保存错误而非转让成功，结果为空（不携带藏品编号、前后
598	// 持有人、版本、历史序号、价款、应付或余款，业务错误为空，不标回放）。
599	// 即使失败后原数据暂时无法读取、状态未能按磁盘重建，这笔转让也必须从当前
600	// 仍打开的登记册中整体撤销：藏品仍属于提交前的持有人、版本不增加、持有
601	// 列表与藏品历史保持原状、版税查询没有本次计算记录、收款账户不多出应付，
602	// 请求号与历史序号都不被消耗；失败前已存在的成功转让、应付与其他藏品记录
603	// 原样保留，随后另一次无关操作成功保存也不会把这笔未保存的转让一并写入。
604	// 读写条件恢复后用原操作者、请求号、原因和全部转让参数重新提交，按当时的
605	// 持有与账户状态重新判断：条件仍满足时正常完成一次转让（版本只增加一次、
606	// 序号紧接已有历史、不标回放），此后再次提交相同内容才回放这一笔已保存的
607	// 结果；恢复期间藏品已被另一笔合法转让转出的，原请求按现有版本冲突规则
608	// 拒绝，不能回放先前未保存的成功。
609	func (r *Registry) Transfer(req TransferRequest) (TransferResult, error) {
610		if err := req.validatePresent(); err != nil {
611			return TransferResult{}, err
612		}
613		r.mu.Lock()
614		defer r.mu.Unlock()
615		if err := r.checkOpen(); err != nil {
616			return TransferResult{}, err
617		}
618	
619		key := requestKey(req.Operator, req.RequestID)
620		sig := transferParamsSig(req)
621		if prev, ok := r.state.Requests[key]; ok {
622			return r.replayTransfer(prev, sig)
623		}
624	
625		bizErr := r.checkTransfer(req)
626		if bizErr != nil {
627			if !isValidationErr(bizErr) {
628				// 状态类业务拒绝（持有人/版本不符、账户停用、收发同人等）
629				// 占用请求号并落盘，相同参数重提永远返回这一次拒绝。
630				r.state.Requests[key] = request{
631					Operator: req.Operator, RequestID: req.RequestID, Kind: "transfer",
632					Params: sig, Rejected: true, Reason: errCode(bizErr),
633					ItemID: req.ItemID,
634				}
635				if err := r.commit(); err != nil {
636					// 拒绝结果落盘失败：这次拒绝没有被记住，与整批转让一致——
637					// 不能只用业务错误掩盖保存错误，调用者稍后用原请求重提时
638					// 必须按当时状态重新判断，而不是回放一个实际没有保存的
639					// 拒绝。commit 失败时已按磁盘内容重建状态，请求记录随之
640					// 撤销；此处再删一次以覆盖磁盘暂时不可读、状态未能重建
641					// 的情形。整体返回空结果：无藏品编号、无持有变化、无历史
642					// 序号、无金额、不标回放、结果中业务错误为空，error 保留
643					// 实际写入错误。
644					delete(r.state.Requests, key)
645					return TransferResult{}, err
646				}
647			}
648			// 藏品或账户不存在等校验错误不占用请求号，也不改变持有或历史。
649			return TransferResult{ItemID: req.ItemID, Err: bizErr}, bizErr
650		}
651	
652		// 回滚基点：本次成功转让的全部改动（持有换人、版本加一、历史、版税
653		// 应付、历史序号、请求结果）都必须以一次保存完成为准。记录改动前的
654		// 持有、历史长度与历史序号，保存失败且磁盘暂时不可读、状态未能按磁盘
655		// 重建时据此整体撤销，否则后续任何一次成功保存都会把这笔未保存的转让
656		// 带进登记册，造成"已换人、可回放"的幻影交易。
657		prevHolding := r.state.Holdings[req.ItemID]
658		prevNextSeq := r.state.NextSeq
659		prevHistLen := len(r.state.History)
660	
661		// 持有变化、历史、版税应付与请求结果在同一临界区内一次落盘。
662		out := r.applyTransfer(req.ItemID, req.ToID, req.Operator, req.Reason, req.RequestID, "", req.Price)
663		r.state.Requests[key] = request{
664			Operator: req.Operator, RequestID: req.RequestID, Kind: "transfer",
665			Params: sig, ItemID: req.ItemID, FromID: out.fromID, ToID: req.ToID,
666			Version: out.toVer(), TxSeq: out.seq,
667		}
668		if err := r.commit(); err != nil {
669			// commit 失败时已尝试按磁盘内容重建状态：重建成功则本次改动已随
670			// 旧状态整体撤销（持有未换人、无本次历史与应付、请求记录不存在、
671			// 序号未消耗），无需再动；磁盘暂时不可读、状态未能重建时本次改动
672			// 仍在，据此把这笔未保存的转让全部撤销，让当前已打开的登记册回到
673			// 提交前状态，也不被随后另一次成功保存带入。返回空结果：无藏品
674			// 编号、无前后持有人、无版本、无历史序号、无价款/应付/余款、不标
675			// 回放、结果中业务错误为空，error 保留实际写入错误。
676			if _, pending := r.state.Requests[key]; pending {
677				delete(r.state.Requests, key)
678				delete(r.state.Royalties, out.seq)
679				r.state.History = r.state.History[:prevHistLen]
680				r.state.Holdings[req.ItemID] = prevHolding
681				r.state.NextSeq = prevNextSeq
682			}
683			return TransferResult{}, err
684		}
685		return TransferResult{ItemID: req.ItemID, FromID: out.fromID, ToID: req.ToID,
686			Version: out.toVer(), TxSeq: out.seq,
687			Price: out.royalty.Price, Payables: publicPayables(out.royalty.Payees),
688			Remainder: out.royalty.Remainder}, nil
689	}
690	
691	// checkTransfer 按单件转让的优先级执行与整批共用的直接转让资格规则：
692	// 参数合法后，藏品及持有记录不存在优先于账户错误，操作者的登记和停用
693	// 问题优先于接收账户问题，接收账户问题优先于收发同人，收发同人又优先
694	// 于持有信息不符。
695	func (r *Registry) checkTransfer(req TransferRequest) error {
696		return r.checkSingleTransferEligibility(directTransferEligibility{
697			itemID:        req.ItemID,
698			operator:      req.Operator,
699			toID:          req.ToID,
700			expectedOwner: req.ExpectedOwner,
701			expectedVer:   req.ExpectedVer,
702		})
703	}
704	
705	func (r *Registry) replayTransfer(prev request, sig string) (TransferResult, error) {
706		if prev.Kind != "transfer" || prev.Params != sig {
707			return TransferResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
708				ErrRequestConflict, prev.Operator, prev.RequestID)
709		}
710		res := TransferResult{ItemID: prev.ItemID, FromID: prev.FromID, ToID: prev.ToID,
711			Version: prev.Version, TxSeq: prev.TxSeq, Replayed: true}
712		if prev.Rejected {
713			res.Err = codeErr(prev.Reason)
714			return res, res.Err
715		}
716		// 回放首次成功的金额：即使藏品后来再次易手或进程重开，仍返回原
717		// 价款与应付明细，不重复计入。
718		res.Price, res.Payables, res.Remainder = r.royaltyOfTx(prev.TxSeq)
719		return res, nil
720	}
