723	
724	// authzCurrentStatus 计算授权当前状态。撤销与使用是落盘的终态；到期不
725	// 落盘，按当前时间实时判断——从到期时间点起即视为已过期。
726	func authzCurrentStatus(a authzRec, now time.Time) string {
727		switch a.Status {
728		case "revoked":
729			return AuthRevoked
730		case "used":
731			return AuthUsed
732		}
733		if !a.ExpiresAt.IsZero() && !now.Before(a.ExpiresAt) {
734			return AuthExpired
735		}
736		return AuthActive
737	}
