899	func (r *Registry) checkCreateAuthorization(req CreateAuthorizationRequest, now time.Time) error {
900		h, ok := r.state.Holdings[req.ItemID]
901		if !ok {
902			if _, itemExists := r.state.Items[req.ItemID]; !itemExists {
903				return fmt.Errorf("%w: 藏品 %s", ErrNotFound, req.ItemID)
904			}
905			return fmt.Errorf("%w: 藏品 %s 没有持有记录", ErrNotFound, req.ItemID)
906		}
907		op, ok := r.state.Accounts[req.Operator]
908		if !ok {
909			return fmt.Errorf("%w: 授权人账户 %s", ErrNotFound, req.Operator)
910		}
911		trustee, ok := r.state.Accounts[req.TrusteeID]
912		if !ok {
913			return fmt.Errorf("%w: 受托人账户 %s", ErrNotFound, req.TrusteeID)
914		}
915		to, ok := r.state.Accounts[req.ToID]
916		if !ok {
917			return fmt.Errorf("%w: 接收账户 %s", ErrNotFound, req.ToID)
918		}
919		if req.TrusteeID == req.Operator {
920			return fmt.Errorf("%w: 受托人不能是授权人 %s", ErrSameAccount, req.Operator)
921		}
922		if req.ToID == req.Operator {
923			return fmt.Errorf("%w: 接收人不能是授权人 %s", ErrSameAccount, req.Operator)
924		}
925		if !op.Active {
926			return fmt.Errorf("%w: 授权人账户 %s", ErrAccountInactive, req.Operator)
927		}
928		if !trustee.Active {
929			return fmt.Errorf("%w: 受托人账户 %s", ErrAccountInactive, req.TrusteeID)
930		}
931		if !to.Active {
932			return fmt.Errorf("%w: 接收账户 %s", ErrAccountInactive, req.ToID)
933		}
934		// 授权编号占用是对象级冲突，优先于当前时间与持有版本检查。
935		if _, exists := r.state.Authzs[req.AuthID]; exists {
936			return fmt.Errorf("%w: 授权编号 %s 已被占用", ErrAlreadyExists, req.AuthID)
937		}
938		// 到期时间不晚于当前时间即为参数错误；从到期时间点起不可使用。
939		if !req.ExpiresAt.After(now) {
940			return fmt.Errorf("%w: 到期时间 %s 必须晚于当前时间",
941				ErrInvalidArgument, req.ExpiresAt.Format(time.RFC3339Nano))
942		}
943		if h.OwnerID != req.ExpectedOwner || h.Version != req.ExpectedVer ||
944			req.Operator != h.OwnerID {
945			return fmt.Errorf("%w: 藏品 %s 当前为 %s 版本 %d",
946				ErrConflict, req.ItemID, h.OwnerID, h.Version)
947		}
948		return nil
949	}
