1159	func proxyTransferParamsSig(req ProxyTransferRequest) string {
1160		b, _ := json.Marshal(struct {
1161			Kind   string `json:"kind"`
1162			AuthID string `json:"auth_id"`
1163			Reason string `json:"reason"`
1164		}{"proxy_transfer", req.AuthID, req.Reason})
1165		return string(b)
1166	}
1167	
1168	// ProxyTransfer 由受托人凭授权发起一次性代转。藏品与接收人均以授权
1169	// 记载为准，请求本身不能指定。成功后持有人变为授权中的接收人、持有
1170	// 版本加一，授权记为已使用并关联该笔转让；代转同样出现在藏品历史中，
1171	// 操作者记为实际受托账户并可通过授权编号追溯。
1172	//
1173	// 非受托人（ErrForbidden）、授权已撤销（ErrAuthorizationRevoked）、
1174	// 已到期（ErrAuthorizationExpired）、已使用（ErrAuthorizationUsed）、
1175	// 任一相关账户停用（ErrAccountInactive）以及持有版本已变化
1176	// （ErrConflict，即使藏品回到授权人手中也不恢复）分别明确拒绝，拒绝
1177	// 不改变持有或授权状态。成功代转用原请求号重放时，即使授权已到期、
1178	// 账户已停用或藏品再次易手，仍返回首次的转让结果。
1179	//
1180	// 上述状态类拒绝以保存完成为准：拒绝结果尚未写入原登记册而保存失败（如
1181	// 数据位置暂时无法写入）时，返回实际保存错误，不能只返回到期、无权或停用
1182	// 等业务拒绝让调用者误以为这次拒绝已经记住；结果为空（不带授权或藏品编号、
1183	// 不带转让和金额信息、不标回放，结果内的业务错误也为空），error 保留实际
1184	// 写入失败原因。这次未保存的拒绝不改变授权内容、使用标记、授权变更记录，
1185	// 也不改变藏品持有人、版本、转让历史与版税应付，并不占用操作者的本次请求
1186	// 号——即使保存失败后原数据暂时无法读取、状态未能按磁盘重建，未保存的拒绝
1187	// 也不能留在当前已打开的登记册中，或随随后另一次成功保存被记住。保存条件
1188	// 恢复后用完全相同的请求重提，按重提时的业务状态重新判断，而不是回放失败
1189	// 时的拒绝（例如到期拒绝保存失败、授权随后被撤销时，重提返回已撤销）；这次
1190	// 重新处理若保存成功不标回放，此后原样重提才回放已保存的结果。已经成功保存
1191	// 的拒绝仍按首次结果回放，改动该请求的业务内容仍报请求号冲突；必填内容缺失
1192	// 或引用不存在沿用原错误且不占用请求号。
1193	//
1194	// 成功代转同样以保存完成为准：持有换人、版本加一、转让历史、版税应付、
1195	// 历史序号、授权使用标记与使用记录、授权历史序号以及请求结果都尚未写入原
1196	// 登记册而保存失败（如数据位置暂时无法写入）时，返回实际保存错误而非代转
1197	// 成功，结果为空（不携带授权或藏品编号、前后持有人、版本、历史序号、价款、
1198	// 应付或余款，业务错误为空，不标回放）。即使失败后原数据暂时无法读取、状态
1199	// 未能按磁盘重建，这笔代转也必须从当前仍打开的登记册中整体撤销：藏品仍属于
1200	// 提交前持有人、版本不增加、双方持有列表与藏品历史保持原状，授权没有使用
1201	// 时间或关联转让序号、授权历史没有本次使用记录，版税查询没有本次计算记录、
1202	// 收款账户不多出应付，请求号、藏品历史序号与授权历史序号都不被消耗；失败前
1203	// 已存在的成功交易、授权与应付原样保留，随后另一次无关操作成功保存也不会把
1204	// 这笔未保存的代转一并写入。读写条件恢复后受托人用原请求号、原因和授权编号
1205	// 重提，按当时的授权、账户与持有状态重新处理：授权仍有效且条件仍满足时真正
1206	// 完成一次代转（版本只增加一次、新增记录接续原有序号、价款仍取授权约定、
1207	// 余款仍归授权人、不标回放），此后原样重提才回放这一笔已保存结果；授权已经
1208	// 到期、撤销或持有版本已经变化时沿用对应拒绝，不能回放那次未保存的成功，也
1209	// 不因恢复状态而延长授权有效期。
1210	func (r *Registry) ProxyTransfer(req ProxyTransferRequest) (ProxyTransferResult, error) {
1211		missing := []string{}
1212		if strings.TrimSpace(req.Operator) == "" {
1213			missing = append(missing, "operator")
1214		}
1215		if strings.TrimSpace(req.Reason) == "" {
1216			missing = append(missing, "reason")
1217		}
1218		if strings.TrimSpace(req.RequestID) == "" {
1219			missing = append(missing, "request_id")
1220		}
1221		if strings.TrimSpace(req.AuthID) == "" {
1222			missing = append(missing, "auth_id")
1223		}
1224		if len(missing) > 0 {
1225			return ProxyTransferResult{}, fmt.Errorf("%w: 代转请求缺少必填字段 %s",
1226				ErrInvalidArgument, strings.Join(missing, ", "))
1227		}
1228		r.mu.Lock()
1229		defer r.mu.Unlock()
1230		if err := r.checkOpen(); err != nil {
1231			return ProxyTransferResult{}, err
1232		}
1233	
1234		now := r.now()
1235		key := requestKey(req.Operator, req.RequestID)
1236		sig := proxyTransferParamsSig(req)
1237		if prev, ok := r.state.Requests[key]; ok {
1238			return r.replayProxyTransfer(prev, sig)
1239		}
1240	
1241		if bizErr := r.checkProxyTransfer(req, now); bizErr != nil {
1242			if !isValidationErr(bizErr) {
1243				// 状态类业务拒绝（无权、已撤销、已到期、已使用、停用、版本已
1244				// 变化）占用请求号并落盘：相同参数重提返回这一次拒绝。
1245				r.state.Requests[key] = request{
1246					Operator: req.Operator, RequestID: req.RequestID, Kind: "proxy_transfer",
1247					Params: sig, Rejected: true, Reason: errCode(bizErr), AuthID: req.AuthID,
1248				}
1249				if err := r.commit(); err != nil {
1250					// 拒绝结果落盘失败：这次拒绝没有被记住，与发行、转让、授权
1251					// 创建/撤销一致——不能用业务错误掩盖保存错误，调用者稍后用
1252					// 原请求重提时必须按当时状态重新判断，而不是回放一个实际没有
1253					// 保存的拒绝。此分支在写入前只动了请求记录，没有改变持有、
1254					// 授权或版税；commit 失败时已按磁盘内容重建状态，请求记录随之
1255					// 撤销，此处再删一次以覆盖磁盘暂时不可读、状态未能重建的情形。
1256					// 整体返回空结果：不带授权或藏品编号、不带转让和金额信息、不标
1257					// 回放、结果中业务错误为空，error 保留实际写入错误。
1258					delete(r.state.Requests, key)
1259					return ProxyTransferResult{}, err
1260				}
1261			}
1262			// 必填缺失、授权或账户不存在等校验错误不占用请求号，也不改变持有、
1263			// 授权状态或授权变更记录。
1264			return ProxyTransferResult{AuthID: req.AuthID, Err: bizErr}, bizErr
1265		}
1266	
1267		a := r.state.Authzs[req.AuthID]
1268		// 回滚基点：本次成功代转的全部改动（持有换人、版本加一、转让历史、
1269		// 版税应付、历史序号、授权使用标记与使用记录、授权历史序号、请求结果）
1270		// 都必须以一次保存完成为准。记录改动前的授权、持有、历史长度与两类
1271		// 历史序号，保存失败且磁盘暂时不可读、状态未能按磁盘重建时据此整体
1272		// 撤销，否则后续任何一次成功保存都会把这笔未保存的代转带进登记册，
1273		// 造成"已换人、授权已用、可回放"的幻影交易。
1274		prevAuthz := a
1275		prevHolding := r.state.Holdings[a.ItemID]
1276		prevNextSeq := r.state.NextSeq
1277		prevHistLen := len(r.state.History)
1278		prevNextAuthSeq := r.state.NextAuthSeq
1279		prevAuthEvents := len(r.state.AuthEvents)
1280	
1281		// 代转价款以授权创建时记载为准，执行时不得改价；余款归转让前持有
1282		// 人（授权人），不记给受托人。持有变化、历史、应付明细与授权使用
1283		// 状态在同一临界区内一次落盘；历史记录实际受托账户并可按授权编号
1284		// 追溯。
1285		out := r.applyTransfer(a.ItemID, a.ToID, req.Operator, req.Reason, req.RequestID, a.ID, a.Price)
1286		a.Status = "used"
1287		a.UsedTxSeq = out.seq
1288		a.UsedAt = now
1289		r.state.Authzs[a.ID] = a
1290		authSeq := prevNextAuthSeq + 1
1291		r.state.NextAuthSeq = authSeq
1292		r.state.AuthEvents = append(r.state.AuthEvents, authzEvent{
1293			Seq: authSeq, AuthID: a.ID, ItemID: a.ItemID, Kind: "use",
1294			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
1295			FromStatus: AuthActive, ToStatus: AuthUsed, TxSeq: out.seq, OccurredAt: now,
1296		})
1297		r.state.Requests[key] = request{
1298			Operator: req.Operator, RequestID: req.RequestID, Kind: "proxy_transfer",
1299			Params: sig, AuthID: a.ID, ItemID: a.ItemID, FromID: out.fromID, ToID: a.ToID,
1300			Version: out.toVer(), TxSeq: out.seq,
1301		}
1302		if err := r.commit(); err != nil {
1303			// commit 失败时已尝试按磁盘内容重建状态：重建成功则本次改动已随
1304			// 旧状态整体撤销（持有未换人、无本次历史与应付、授权未使用、无本次
1305			// 使用记录、请求记录不存在、两类序号未消耗），无需再动；磁盘暂时
1306			// 不可读、状态未能重建时本次改动仍在，据此把这笔未保存的代转全部
1307			// 撤销，让当前已打开的登记册回到提交前状态，也不被随后另一次成功
1308			// 保存带入。返回空结果：无授权或藏品编号、无前后持有人、无版本、无
1309			// 历史序号、无价款/应付/余款、不标回放、结果中业务错误为空，error
1310			// 保留实际写入错误。
1311			if _, pending := r.state.Requests[key]; pending {
1312				delete(r.state.Requests, key)
1313				delete(r.state.Royalties, out.seq)
1314				r.state.History = r.state.History[:prevHistLen]
1315				r.state.Holdings[a.ItemID] = prevHolding
1316				r.state.NextSeq = prevNextSeq
1317				r.state.AuthEvents = r.state.AuthEvents[:prevAuthEvents]
1318				r.state.NextAuthSeq = prevNextAuthSeq
1319				r.state.Authzs[a.ID] = prevAuthz
1320			}
1321			return ProxyTransferResult{}, err
1322		}
1323		return ProxyTransferResult{AuthID: a.ID, ItemID: a.ItemID, FromID: out.fromID,
1324			ToID: a.ToID, Version: out.toVer(), TxSeq: out.seq,
1325			Price: out.royalty.Price, Payables: publicPayables(out.royalty.Payees),
1326			Remainder: out.royalty.Remainder}, nil
1327	}
1328	
1329	func (r *Registry) checkProxyTransfer(req ProxyTransferRequest, now time.Time) error {
1330		a, ok := r.state.Authzs[req.AuthID]
1331		if !ok {
1332			return fmt.Errorf("%w: 授权 %s", ErrNotFound, req.AuthID)
1333		}
1334		op, ok := r.state.Accounts[req.Operator]
1335		if !ok {
1336			return fmt.Errorf("%w: 受托人账户 %s", ErrNotFound, req.Operator)
1337		}
1338		granter, gOk := r.state.Accounts[a.GranterID]
1339		to, tOk := r.state.Accounts[a.ToID]
1340		if req.Operator != a.TrusteeID {
1341			return fmt.Errorf("%w: 账户 %s 不是授权 %s 的受托人",
1342				ErrForbidden, req.Operator, req.AuthID)
1343		}
1344		if !gOk {
1345			return fmt.Errorf("%w: 授权人账户 %s", ErrNotFound, a.GranterID)
1346		}
1347		if !tOk {
1348			return fmt.Errorf("%w: 接收账户 %s", ErrNotFound, a.ToID)
1349		}
1350		if !op.Active {
1351			return fmt.Errorf("%w: 受托人账户 %s", ErrAccountInactive, req.Operator)
1352		}
1353		if !granter.Active {
1354			return fmt.Errorf("%w: 授权人账户 %s", ErrAccountInactive, a.GranterID)
1355		}
1356		if !to.Active {
1357			return fmt.Errorf("%w: 接收账户 %s", ErrAccountInactive, a.ToID)
1358		}
1359		switch authzCurrentStatus(a, now) {
1360		case AuthRevoked:
1361			return fmt.Errorf("%w: 授权 %s", ErrAuthorizationRevoked, req.AuthID)
1362		case AuthExpired:
1363			return fmt.Errorf("%w: 授权 %s", ErrAuthorizationExpired, req.AuthID)
1364		case AuthUsed:
1365			return fmt.Errorf("%w: 授权 %s", ErrAuthorizationUsed, req.AuthID)
1366		}
1367		// 授权只在创建时绑定的持有版本上有效；版本单调递增，藏品即使回到
1368		// 授权人手中也不会回到旧版本，旧授权据此永久失效。
1369		h, ok := r.state.Holdings[a.ItemID]
1370		if !ok {
1371			return fmt.Errorf("%w: 藏品 %s 没有持有记录", ErrNotFound, a.ItemID)
1372		}
1373		if h.OwnerID != a.GranterID || h.Version != a.GrantVer {
1374			return fmt.Errorf("%w: 藏品 %s 当前为 %s 版本 %d，授权绑定 %s 版本 %d",
1375				ErrConflict, a.ItemID, h.OwnerID, h.Version, a.GranterID, a.GrantVer)
1376		}
1377		return nil
1378	}
1379	
1380	func (r *Registry) replayProxyTransfer(prev request, sig string) (ProxyTransferResult, error) {
1381		if prev.Kind != "proxy_transfer" || prev.Params != sig {
1382			return ProxyTransferResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
1383				ErrRequestConflict, prev.Operator, prev.RequestID)
1384		}
1385		res := ProxyTransferResult{AuthID: prev.AuthID, ItemID: prev.ItemID, FromID: prev.FromID,
1386			ToID: prev.ToID, Version: prev.Version, TxSeq: prev.TxSeq, Replayed: true}
1387		if prev.Rejected {
1388			res.Err = codeErr(prev.Reason)
1389			return res, res.Err
1390		}
1391		// 回放首次成功的金额：授权到期、账户停用或藏品再次易手后仍返回
1392		// 原价款与应付明细，不重复计入。
1393		res.Price, res.Payables, res.Remainder = r.royaltyOfTx(prev.TxSeq)
1394		return res, nil
1395	}
