		if err != nil {
			t.Fatalf("GetHolding %s: %v", id, err)
		}
		if h.OwnerID != "bob" || h.Version != 1 {
			t.Fatalf("失败后 %s 持有被改变: %+v", id, h)
		}
		hist, err := r.History(id)
		if err != nil {
			t.Fatalf("History %s: %v", id, err)
		}
		if len(hist) != 1 || hist[0].Kind != "issue" {

